function CareerPlanner({notify}:{notify:(s:string)=>void}){
 const [selected,setSelected]=useState("UI设计师");
 const [plans,setPlans]=useState<CareerPlan[]>([{id:"demo-plan-1",role:"UI设计师",created:"2026-10-31",tasks:roleTemplates[0].tasks.map((t,i)=>({id:"demo-task-"+i,category:t[0],title:t[1],detail:t[2],done:i===0}))}]);
 const [showCreate,setShowCreate]=useState(false);const [expanded,setExpanded]=useState<string|null>("demo-plan-1");
 const [mode,setMode]=useState<"demo"|"cloud">("demo");const [loading,setLoading]=useState(false);const [saving,setSaving]=useState(false);
 const activeRole=roleTemplates.find(r=>r.role===selected)??roleTemplates[0];
 const total=plans.reduce((n,p)=>n+p.tasks.length,0);const completed=plans.reduce((n,p)=>n+p.tasks.filter(t=>t.done).length,0);const percent=total?Math.round(completed/total*100):0;
 useEffect(()=>{const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)return;const supabase=createBrowserClient(url,key);let alive=true;(async()=>{const {data:{user},error:authError}=await supabase.auth.getUser();if(!alive||authError||!user)return;setLoading(true);const {data:paths,error}=await supabase.from("learning_paths").select("id,title,target_role,description,status,created_at").eq("user_id",user.id).order("created_at",{ascending:false});if(!alive)return;if(error){notify("成长路径云端读取失败，暂时保留演示数据："+error.message);setLoading(false);return;}const ids=(paths??[]).map(p=>p.id);let nodes:any[]=[];if(ids.length){const {data,error:nodeError}=await supabase.from("path_nodes").select("id,path_id,title,category,description,sort_order,status,completed_at").in("path_id",ids).order("sort_order",{ascending:true});if(nodeError){notify("阶段任务读取失败："+nodeError.message);setLoading(false);return;}nodes=nodes??[];}const mapped=(paths??[]).map(p=>({id:p.id,role:p.target_role||p.title,created:new Date(p.created_at).toLocaleDateString("zh-CN"),tasks:nodes.filter(n=>n.path_id===p.id).map(n=>({id:n.id,title:n.title,category:n.category||"学习阶段",detail:n.description||"",done:n.status==="completed"}))}));setPlans(mapped);setExpanded(mapped[0]?.id??null);setMode("cloud");setLoading(false);})();return()=>{alive=false;};},[]);
 const createPlan=async()=>{if(plans.some(p=>p.role===selected)){notify("该岗位已有成长规划，可直接继续完善");setShowCreate(false);setExpanded(plans.find(p=>p.role===selected)!.id);return;}setSaving(true);try{const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;let created:CareerPlan;if(mode==="cloud"&&url&&key){const supabase=createBrowserClient(url,key);const {data:{user},error:authError}=await supabase.auth.getUser();if(authError||!user)throw new Error("登录状态已失效，请重新登录");const {data:path,error}=await supabase.from("learning_paths").insert({user_id:user.id,title:activeRole.role,target_role:activeRole.role,description:activeRole.summary,status:"active",progress:0}).select("id,created_at").single();if(error)throw error;const payload=activeRole.tasks.map((t,i)=>({path_id:path.id,title:t[1],category:t[0],description:t[2],sort_order:i,status:"todo"}));const {data:nodes,error:nodeError}=await supabase.from("path_nodes").insert(payload).select("id,title,category,description,status,sort_order");if(nodeError){await supabase.from("learning_paths").delete().eq("id",path.id).eq("user_id",user.id);throw nodeError;}created={id:path.id,role:activeRole.role,created:new Date(path.created_at).toLocaleDateString("zh-CN"),tasks:(nodes??[]).sort((a,b)=>a.sort_order-b.sort_order).map(n=>({id:n.id,title:n.title,category:n.category||"学习阶段",detail:n.description||"",done:n.status==="completed"}))};}else{const id="local-"+Date.now();created={id,role:selected,created:new Date().toLocaleDateString("zh-CN"),tasks:activeRole.tasks.map((t,i)=>({id:id+"-"+i,category:t[0],title:t[1],detail:t[2],done:false}))};}
 setPlans(prev=>[...prev,created]);setExpanded(created.id);setShowCreate(false);notify(mode==="cloud"?"成长规划已保存到云端":"已创建本地演示成长规划");}catch(e){notify(e instanceof Error?e.message:"创建成长规划失败");}finally{setSaving(false);}};
 const toggleTask=async(planId:string,taskId:string)=>{const plan=plans.find(p=>p.id===planId);const task=plan?.tasks.find(t=>t.id===taskId);if(!task)return;const nextDone=!task.done;if(mode==="cloud"){const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)return;const supabase=createBrowserClient(url,key);const {error}=await supabase.from("path_nodes").update({status:nextDone?"completed":"todo",completed_at:nextDone?new Date().toISOString():null}).eq("id",taskId).eq("path_id",planId);if(error){notify("任务状态保存失败："+error.message);return;}}
 setPlans(prev=>prev.map(p=>p.id!==planId?p:{...p,tasks:p.tasks.map(t=>t.id!==taskId?t:{...t,done:nextDone})}));};
 const deletePlan=async(id:string)=>{if(mode==="cloud"){const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)return;const supabase=createBrowserClient(url,key);const {data:{user}}=await supabase.auth.getUser();if(!user){notify("登录状态已失效，请重新登录");return;}const {error}=await supabase.from("learning_paths").delete().eq("id",id).eq("user_id",user.id);if(error){notify("删除失败："+error.message);return;}}setPlans(prev=>prev.filter(p=>p.id!==id));if(expanded===id)setExpanded(null);notify(mode==="cloud"?"成长规划已删除":"已移除本地演示规划");};
 return <div className="space-y-4">
  <div className="flex flex-wrap items-end justify-between gap-3"><div><h1 className="text-sm font-semibold">职业规划与成长路径</h1><p className="mt-1 text-xs text-slate-400">从目标岗位出发，将能力要求拆解为可执行、可追踪的成长任务</p></div><span className={`rounded px-2.5 py-1.5 text-[10px] ${mode==="cloud"?"bg-emerald-50 text-emerald-700":"bg-amber-50 text-amber-700"}`}>{loading?"正在同步…":mode==="cloud"?"云端账号数据 · 已连接":"演示模式 · 本地临时数据"}</span></div>
  <div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><Metric icon={Target} label="目标岗位" value={String(new Set(plans.map(p=>p.role)).size)} tone="bg-violet-50 text-violet-500"/><Metric icon={Layers} label="成长任务" value={String(total)} tone="bg-amber-50 text-amber-500"/><Metric icon={CheckCircle2} label="已完成任务" value={String(completed)} tone="bg-emerald-50 text-emerald-500"/><Metric icon={TrendingUp} label="整体成长进度" value={percent+"%"} tone="bg-blue-50 text-blue-500"/></div>
  <section className="panel p-4"><div className="mb-4 flex flex-wrap items-center justify-between gap-2"><div><b className="text-sm">探索职业方向</b><p className="mt-1 text-xs text-slate-400">选择感兴趣的岗位，了解岗位定位与关键能力</p></div><button onClick={()=>setShowCreate(true)} className="rounded bg-[#8454F5] px-3 py-2 text-xs text-white hover:bg-[#7343E4]">＋ 创建成长规划</button></div><div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-5">{roleTemplates.map(role=><button key={role.role} onClick={()=>setSelected(role.role)} className={`rounded border p-3 text-left transition ${selected===role.role?"border-[#8454F5] bg-[#F3F1FD]":"border-[#eeeaf4] hover:border-[#d9cafa]"}`}><div className="flex items-center justify-between"><span className="text-xs font-semibold">{role.role}</span><span className="text-[10px] text-[#8454F5]">{role.match}%</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#eeeaf4]"><div className="h-full rounded-full bg-[#8454F5]" style={{width:role.match+"%"}}/></div><p className="mt-2 line-clamp-2 text-[10px] leading-4 text-slate-400">{role.summary}</p></button>)}</div><div className="mt-4 grid gap-4 rounded bg-[#FAF9FC] p-4 md:grid-cols-[1.2fr_1fr]"><div><div className="text-xs text-slate-400">当前选择</div><h2 className="mt-1 text-lg font-semibold">{activeRole.role}</h2><p className="mt-2 max-w-xl text-xs leading-5 text-[#575363]">{activeRole.summary}</p></div><div><div className="mb-2 text-xs font-medium">核心能力要求</div><div className="flex flex-wrap gap-2">{activeRole.skills.map(skill=><Tag key={skill}>{skill}</Tag>)}</div></div></div></section>
  <section className="panel p-4"><div className="mb-4 flex flex-wrap items-center justify-between gap-2"><div><b className="text-sm">我的成长路径</b><p className="mt-1 text-xs text-slate-400">将长期目标拆解为阶段任务，逐步积累可展示的能力成果</p></div><span className="text-xs text-slate-400">{completed}/{total} 项任务已完成</span></div>{plans.length===0?<div className="rounded bg-[#FAF9FC] py-12 text-center"><Target className="mx-auto text-[#9C88EC]" size={28}/><p className="mt-3 text-sm text-slate-500">还没有成长规划</p><p className="mt-1 text-xs text-slate-400">先选择一个目标岗位，创建你的第一条成长路径</p></div>:<div className="space-y-3">{plans.map(plan=>{const done=plan.tasks.filter(t=>t.done).length;const pct=plan.tasks.length?Math.round(done/plan.tasks.length*100):0;return <div key={plan.id} className="overflow-hidden rounded border border-[#eeeaf4]"><button onClick={()=>setExpanded(expanded===plan.id?null:plan.id)} className="flex w-full flex-wrap items-center gap-3 p-3 text-left hover:bg-[#FCFBFE]"><div className="grid h-9 w-9 place-items-center rounded bg-[#F3F1FD] text-[#8454F5]"><Target size={17}/></div><div className="min-w-[130px] flex-1"><div className="text-xs font-semibold">{plan.role}</div><div className="mt-1 text-[10px] text-slate-400">创建于 {plan.created} · {plan.tasks.length} 个阶段任务</div></div><div className="w-28"><div className="mb-1 flex justify-between text-[10px] text-slate-400"><span>完成进度</span><b className="text-[#8454F5]">{pct}%</b></div><div className="h-1.5 rounded-full bg-[#eeeaf4]"><div className="h-1.5 rounded-full bg-[#8454F5]" style={{width:pct+"%"}}/></div></div><ChevronRight size={16} className={`text-slate-400 transition ${expanded===plan.id?"rotate-90":""}`}/></button>{expanded===plan.id&&<div className="border-t bg-white p-3"><div className="relative ml-4 space-y-0 border-l border-dashed border-[#d9cafa]">{plan.tasks.map((task,i)=><div key={task.id} className="relative pb-4 pl-6 last:pb-1"><span className={`absolute -left-[7px] top-1 h-3 w-3 rounded-full border-2 border-white ${task.done?"bg-emerald-500":"bg-[#9C88EC]"}`}/><div className="flex items-start gap-3"><input type="checkbox" checked={task.done} onChange={()=>toggleTask(plan.id,task.id)} className="mt-0.5 h-4 w-4 accent-[#8454F5]"/><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="text-[10px] text-[#9C88EC]">阶段 {i+1} · {task.category}</span>{task.done&&<span className="rounded bg-emerald-50 px-1.5 py-0.5 text-[9px] text-emerald-600">已完成</span>}</div><div className={`mt-1 text-xs font-medium ${task.done?"text-slate-400 line-through":"text-[#091335]"}`}>{task.title}</div><p className="mt-1 text-[11px] leading-5 text-slate-400">{task.detail}</p></div></div></div>)}</div><div className="mt-3 flex justify-end"><button onClick={()=>deletePlan(plan.id)} className="text-[11px] text-slate-400 hover:text-rose-500">删除规划</button></div></div>}</div>})}</div>}</section>
  {showCreate&&<div className="fixed inset-0 z-[55] flex items-center justify-center bg-black/25 p-4" onClick={()=>setShowCreate(false)}><div className="w-full max-w-md rounded-lg bg-white p-5 shadow-xl" onClick={e=>e.stopPropagation()}><div className="flex items-center justify-between"><b className="text-sm">创建成长规划</b><button onClick={()=>setShowCreate(false)}><X size={16}/></button></div><p className="mt-2 text-xs leading-5 text-slate-400">{mode==="cloud"?"规划和阶段任务将保存到当前账号。":"当前为本地演示模式，配置并登录 Supabase 后可跨设备保存。"}</p><label className="mb-2 mt-4 block text-xs text-slate-500">目标岗位</label><select value={selected} onChange={e=>setSelected(e.target.value)} className="w-full rounded border border-[#eeeaf4] bg-white px-3 py-2 text-sm outline-none focus:border-[#8454F5]">{roleTemplates.map(r=><option key={r.role}>{r.role}</option>)}</select><div className="mt-5 flex justify-end gap-2"><button onClick={()=>setShowCreate(false)} className="rounded border px-4 py-2 text-xs">取消</button><button disabled={saving} onClick={createPlan} className="rounded bg-[#8454F5] px-4 py-2 text-xs text-white disabled:opacity-60">{saving?"保存中…":"生成成长路径"}</button></div></div></div>}
 </div>;
}

export default function Home(){
 const [accountEmail,setAccountEmail]=useState("");
 const [profile,setProfile]=useState({display_name:"设计学习者",major:"",school:"",grade:"",career_goal:"",bio:""});const [profileEditing,setProfileEditing]=useState(false);const [profileSaving,setProfileSaving]=useState(false);const [profileDraft,setProfileDraft]=useState({display_name:"设计学习者",major:"",school:"",grade:"",career_goal:"",bio:""});
 const [section,setSection]=useState<Section>("交集");const [profileTab,setProfileTab]=useState("作品");const [graphView,setGraphView]=useState<"grid"|"list">("list");const [query,setQuery]=useState("");const [showNew,setShowNew]=useState(false);const [toast,setToast]=useState("");const [mobileNav,setMobileNav]=useState(false);
 const [savedResources,setSavedResources]=useState<any[]>([]);const [resourceMode,setResourceMode]=useState<"demo"|"cloud">("demo");const [resourceLoading,setResourceLoading]=useState(false);const [resourceSaving,setResourceSaving]=useState(false);const [studyRecords,setStudyRecords]=useState<any[]>([]);const [profileAssessments,setProfileAssessments]=useState<any[]>([]);const [assessmentLoading,setAssessmentLoading]=useState(false);const [studyForm,setStudyForm]=useState({title:"",record_type:"课程学习",minutes:"30",note:""});const [studySaving,setStudySaving]=useState(false);
 const [projectItems,setProjectItems]=useState<ProjectRecord[]>(demoProjects);const [projectMode,setProjectMode]=useState<"demo"|"cloud">("demo");const [projectLoading,setProjectLoading]=useState(false);const [projectSaving,setProjectSaving]=useState(false);const [editingProject,setEditingProject]=useState<string|null>(null);const [projectModal,setProjectModal]=useState(false);const [projectForm,setProjectForm]=useState({title:"",description:"",category:"交互设计",status:"planning" as ProjectRecord["status"],start_date:"",end_date:""});
 const [portfolioItems,setPortfolioItems]=useState<any[]>([]);
 const [portfolioMode,setPortfolioMode]=useState<"demo"|"cloud">("demo");
 const [portfolioLoading,setPortfolioLoading]=useState(false);
 const [portfolioSaving,setPortfolioSaving]=useState(false);
 const [portfolioModal,setPortfolioModal]=useState(false);
 const [editingPortfolio,setEditingPortfolio]=useState<string|null>(null);
 const [portfolioFile,setPortfolioFile]=useState<File|null>(null);
 const [portfolioForm,setPortfolioForm]=useState({title:"",description:"",tags:""});
 const notify=(s:string)=>{setToast(s);setTimeout(()=>setToast(""),2400)};
 useEffect(()=>{const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)return;const supabase=createBrowserClient(url,key);let alive=true;(async()=>{const {data:{user},error:authError}=await supabase.auth.getUser();if(!alive||authError||!user)return;setAssessmentLoading(true);const {data,error}=await supabase.from("skill_assessments").select("self_rating,assessed_at,knowledge_nodes(title,category)").eq("user_id",user.id).order("assessed_at",{ascending:false});if(!alive)return;if(error){notify("能力评估读取失败："+error.message);}else setProfileAssessments(data??[]);setAssessmentLoading(false);})();return()=>{alive=false;};},[]);
 const profileRadar=profileAssessments.map(row=>{const node=Array.isArray(row.knowledge_nodes)?row.knowledge_nodes[0]:row.knowledge_nodes;return node?.title?{subject:node.title,A:Math.round(Number(row.self_rating)*20)}:null;}).filter(Boolean);
 const profileGrowth=(()=>{const months=new Map<string,number>();studyRecords.forEach(record=>{if(!record.created_at)return;const date=new Date(record.created_at);if(Number.isNaN(date.getTime()))return;const label=`${date.getMonth()+1}月`;months.set(label,(months.get(label)??0)+Math.max(0,Number(record.minutes)||0));});return Array.from(months,([month,minutes])=>({month,value:minutes})).reverse();})();
 useEffect(()=>{const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)return;const supabase=createBrowserClient(url,key);let alive=true;(async()=>{const {data:{user},error:authError}=await supabase.auth.getUser();if(!alive||authError||!user)return;setPortfolioLoading(true);const {data,error}=await supabase.from("portfolio_items").select("id,title,cover_url,description,tags,created_at").eq("owner_id",user.id).order("created_at",{ascending:false});if(!alive)return;if(error){notify("作品集读取失败："+error.message);setPortfolioLoading(false);return;}setPortfolioItems(data??[]);setPortfolioMode("cloud");setPortfolioLoading(false);})();return()=>{alive=false;};},[]);
 useEffect(()=>{const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)return;const supabase=createBrowserClient(url,key);let alive=true;(async()=>{const {data:{user},error:authError}=await supabase.auth.getUser();if(!alive)return;if(authError||!user)return;setAccountEmail(user.email??"");const {data:profileData}=await supabase.from("profiles").select("display_name,major,school,grade,career_goal,bio").eq("id",user.id).maybeSingle();if(alive&&profileData){const nextProfile={display_name:profileData.display_name??"设计学习者",major:profileData.major??"",school:profileData.school??"",grade:profileData.grade??"",career_goal:profileData.career_goal??"",bio:profileData.bio??""};setProfile(nextProfile);setProfileDraft(nextProfile);}setProjectLoading(true);const {data,error}=await supabase.from("projects").select("id,title,description,category,status,start_date,end_date,created_at").eq("owner_id",user.id).order("created_at",{ascending:false});if(!alive)return;if(error){notify("项目云端读取失败，当前保留演示数据："+error.message);setProjectLoading(false);return;}setProjectItems((data??[]).map(p=>({...p,description:p.description??"",category:p.category??"未分类",status:(["planning","active","completed","cancelled"].includes(p.status)?p.status:"planning") as ProjectRecord["status"]})));setProjectMode("cloud");setProjectLoading(false);})();return()=>{alive=false;};},[]);
 useEffect(()=>{const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)return;const supabase=createBrowserClient(url,key);let alive=true;(async()=>{const {data:{user},error:authError}=await supabase.auth.getUser();if(!alive||authError||!user)return;setResourceLoading(true);const [resourceResult,recordResult]=await Promise.all([supabase.from("resources").select("id,title,resource_type,url,description,tags,created_at").eq("owner_id",user.id).order("created_at",{ascending:false}),supabase.from("learning_records").select("id,title,record_type,minutes,note,created_at").eq("user_id",user.id).order("created_at",{ascending:false}).limit(20)]);if(!alive)return;if(resourceResult.error){notify("个人资源读取失败："+resourceResult.error.message);}else{setSavedResources(resourceResult.data??[]);setResourceMode("cloud");}if(recordResult.error){notify("学习记录读取失败："+recordResult.error.message);}else setStudyRecords(recordResult.data??[]);setResourceLoading(false);})();return()=>{alive=false;};},[]);
 const saveResource=async(r:(typeof resources)[number])=>{if(savedResources.some(x=>x.title===r.title)){notify("该资源已收藏");return;}setResourceSaving(true);try{if(resourceMode==="cloud"){const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)throw new Error("数据库配置缺失");const supabase=createBrowserClient(url,key);const {data:{user},error:authError}=await supabase.auth.getUser();if(authError||!user)throw new Error("登录状态已失效，请重新登录");const {data,error}=await supabase.from("resources").insert({owner_id:user.id,title:r.title,resource_type:r.type,url:null,description:"从资源推荐中收藏",tags:r.tags,visibility:"private"}).select("id,title,resource_type,url,description,tags,created_at").single();if(error)throw error;setSavedResources(prev=>[data,...prev]);}else setSavedResources(prev=>[{id:"local-"+Date.now(),title:r.title,resource_type:r.type,tags:r.tags,created_at:new Date().toISOString()},...prev]);notify(resourceMode==="cloud"?"已收藏到云端资源库":"已加入本地演示收藏");}catch(e){notify(e instanceof Error?e.message:"收藏失败");}finally{setResourceSaving(false);}};
 const removeResource=async(id:string)=>{try{if(resourceMode==="cloud"){const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)throw new Error("数据库配置缺失");const supabase=createBrowserClient(url,key);const {data:{user}}=await supabase.auth.getUser();if(!user)throw new Error("请先登录");const {error}=await supabase.from("resources").delete().eq("id",id).eq("owner_id",user.id);if(error)throw error;}setSavedResources(prev=>prev.filter(r=>r.id!==id));notify("已从个人资源库移除");}catch(e){notify(e instanceof Error?e.message:"移除失败");}};
 const saveStudyRecord=async()=>{const minutes=Number(studyForm.minutes);if(!studyForm.title.trim()||!Number.isInteger(minutes)||minutes<1||minutes>1440){notify("请填写学习主题，并输入 1–1440 分钟的有效时长");return;}setStudySaving(true);try{const payload={title:studyForm.title.trim(),record_type:studyForm.record_type,minutes,note:studyForm.note.trim()||null};const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(url&&key){const supabase=createBrowserClient(url,key);const {data:{user},error:authError}=await supabase.auth.getUser();if(authError||!user)throw new Error("请先登录后记录学习时长");const {data,error}=await supabase.from("learning_records").insert({...payload,user_id:user.id}).select("id,title,record_type,minutes,note,created_at").single();if(error)throw error;setStudyRecords(prev=>[data,...prev].slice(0,20));}else setStudyRecords(prev=>[{...payload,id:"local-"+Date.now(),created_at:new Date().toISOString()},...prev].slice(0,20));setStudyForm({title:"",record_type:"课程学习",minutes:"30",note:""});notify(url&&key?"学习记录已保存到云端":"学习记录已保存到本地演示状态");}catch(e){notify(e instanceof Error?e.message:"保存学习记录失败");}finally{setStudySaving(false);}};
 const saveProfile=async()=>{if(!profileDraft.display_name.trim()){notify("请填写昵称");return;}const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key){setProfile(profileDraft);setProfileEditing(false);notify("个人资料已更新（本地演示）");return;}setProfileSaving(true);try{const supabase=createBrowserClient(url,key);const {data:{user},error:authError}=await supabase.auth.getUser();if(authError||!user)throw new Error("登录状态已失效，请重新登录");const payload={...profileDraft,display_name:profileDraft.display_name.trim(),updated_at:new Date().toISOString()};const {error}=await supabase.from("profiles").upsert({id:user.id,...payload});if(error)throw error;setProfile(payload);setProfileEditing(false);notify("个人资料已保存");}catch(e){notify(e instanceof Error?e.message:"个人资料保存失败");}finally{setProfileSaving(false);}};

 const openPortfolioModal=(item?:any)=>{setEditingPortfolio(item?.id??null);setPortfolioForm(item?{title:item.title??"",description:item.description??"",tags:(item.tags??[]).join(", ")}:{title:"",description:"",tags:""});setPortfolioFile(null);setPortfolioModal(true);};
 const portfolioStoragePath=(url:string|null|undefined,userId:string)=>{if(!url)return null;try{const parsed=new URL(url);const marker="/storage/v1/object/public/portfolio/";const index=parsed.pathname.indexOf(marker);if(index<0)return null;const path=decodeURIComponent(parsed.pathname.slice(index+marker.length));return path.startsWith(userId+"/")?path:null;}catch{return null;}};
 const savePortfolio=async()=>{if(!portfolioForm.title.trim()){notify("请填写作品名称");return;}if(portfolioMode!=="cloud"){const local={id:editingPortfolio??"local-"+Date.now(),title:portfolioForm.title.trim(),description:portfolioForm.description.trim(),tags:portfolioForm.tags.split(/[,，]/).map(x=>x.trim()).filter(Boolean),cover_url:portfolioFile?URL.createObjectURL(portfolioFile):"",created_at:new Date().toISOString()};setPortfolioItems(prev=>editingPortfolio?prev.map(x=>x.id===editingPortfolio?{...x,...local}:x):[local,...prev]);setPortfolioModal(false);notify("作品已保存到本地演示状态；配置 Supabase 后可云端保存");return;}setPortfolioSaving(true);let uploadedPath:string|null=null;try{const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)throw new Error("Supabase 配置缺失");const supabase=createBrowserClient(url,key);const {data:{user},error:authError}=await supabase.auth.getUser();if(authError||!user)throw new Error("请先登录后管理作品");const previous=portfolioItems.find(x=>x.id===editingPortfolio);let coverUrl=previous?.cover_url??null;if(portfolioFile){if(!["image/jpeg","image/png","image/webp","image/gif"].includes(portfolioFile.type))throw new Error("仅支持 JPG、PNG、WebP 或 GIF 图片");if(portfolioFile.size>10*1024*1024)throw new Error("图片不能超过 10MB");const ext=portfolioFile.name.split(".").pop()?.toLowerCase()||"jpg";uploadedPath=user.id+"/"+crypto.randomUUID()+"."+ext;const {error:uploadError}=await supabase.storage.from("portfolio").upload(uploadedPath,portfolioFile,{contentType:portfolioFile.type,cacheControl:"3600",upsert:false});if(uploadError)throw uploadError;coverUrl=supabase.storage.from("portfolio").getPublicUrl(uploadedPath).data.publicUrl;}const payload={title:portfolioForm.title.trim(),description:portfolioForm.description.trim()||null,tags:portfolioForm.tags.split(/[,，]/).map(x=>x.trim()).filter(Boolean),cover_url:coverUrl};if(editingPortfolio){const {data,error}=await supabase.from("portfolio_items").update(payload).eq("id",editingPortfolio).eq("owner_id",user.id).select("id,title,cover_url,description,tags,created_at").single();if(error)throw error;setPortfolioItems(prev=>prev.map(x=>x.id===editingPortfolio?data:x));}else{const {data,error}=await supabase.from("portfolio_items").insert({...payload,owner_id:user.id}).select("id,title,cover_url,description,tags,created_at").single();if(error)throw error;setPortfolioItems(prev=>[data,...prev]);}if(portfolioFile&&previous?.cover_url){const oldPath=portfolioStoragePath(previous.cover_url,user.id);if(oldPath){const {error:cleanupError}=await supabase.storage.from("portfolio").remove([oldPath]);if(cleanupError)notify("作品已保存，但旧封面清理失败："+cleanupError.message);}}setPortfolioModal(false);notify("作品已保存到云端");}catch(e){if(uploadedPath){const cleanupClient=createBrowserClient(process.env.NEXT_PUBLIC_SUPABASE_URL!,process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!);await cleanupClient.storage.from("portfolio").remove([uploadedPath]).catch(()=>undefined);}notify(e instanceof Error?e.message:"作品保存失败");}finally{setPortfolioSaving(false);}};
 const deletePortfolio=async(id:string)=>{if(portfolioMode==="cloud"){try{const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)throw new Error("Supabase 配置缺失");const supabase=createBrowserClient(url,key);const {data:{user},error:authError}=await supabase.auth.getUser();if(authError||!user)throw new Error("请先登录");const target=portfolioItems.find(item=>item.id===id);const {error}=await supabase.from("portfolio_items").delete().eq("id",id).eq("owner_id",user.id);if(error)throw error;const storagePath=portfolioStoragePath(target?.cover_url,user.id);if(storagePath){const {error:cleanupError}=await supabase.storage.from("portfolio").remove([storagePath]);if(cleanupError)notify("作品记录已删除，但封面文件清理失败："+cleanupError.message);}}catch(e){notify(e instanceof Error?e.message:"删除作品失败");return;}}setPortfolioItems(prev=>prev.filter(x=>x.id!==id));notify(portfolioMode==="cloud"?"作品已删除":"演示作品已移除");};
 const openProjectModal=(p?:ProjectRecord)=>{setEditingProject(p?.id??null);setProjectForm(p?{title:p.title,description:p.description,category:p.category,status:p.status,start_date:p.start_date??"",end_date:p.end_date??""}:{title:"",description:"",category:"交互设计",status:"planning",start_date:"",end_date:""});setProjectModal(true);};
 const saveProject=async()=>{if(!projectForm.title.trim()){notify("请先填写项目名称");return;}if(projectForm.start_date&&projectForm.end_date&&projectForm.end_date<projectForm.start_date){notify("结束日期不能早于开始日期");return;}setProjectSaving(true);try{const payload={title:projectForm.title.trim(),description:projectForm.description.trim()||null,category:projectForm.category,status:projectForm.status,start_date:projectForm.start_date||null,end_date:projectForm.end_date||null};if(projectMode==="cloud"){const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)throw new Error("数据库配置缺失");const supabase=createBrowserClient(url,key);const {data:{user},error:authError}=await supabase.auth.getUser();if(authError||!user)throw new Error("登录状态已失效，请重新登录");if(editingProject){const {data,error}=await supabase.from("projects").update(payload).eq("id",editingProject).eq("owner_id",user.id).select("id,title,description,category,status,start_date,end_date,created_at").single();if(error)throw error;setProjectItems(prev=>prev.map(p=>p.id===editingProject?{...data,description:data.description??"",category:data.category??"未分类"}:p));}else{const {data,error}=await supabase.from("projects").insert({...payload,owner_id:user.id}).select("id,title,description,category,status,start_date,end_date,created_at").single();if(error)throw error;setProjectItems(prev=>[{...data,description:data.description??"",category:data.category??"未分类"},...prev]);}}else if(editingProject){setProjectItems(prev=>prev.map(p=>p.id===editingProject?{...p,...payload,description:payload.description??""}:p));}else{setProjectItems(prev=>[{id:"local-"+Date.now(),...payload,description:payload.description??"",created_at:new Date().toISOString()},...prev]);}setProjectModal(false);notify(projectMode==="cloud"?"项目已保存到云端":"项目已保存到本地演示数据");}catch(e){notify(e instanceof Error?e.message:"项目保存失败");}finally{setProjectSaving(false);}};
 const deleteProject=async(id:string)=>{if(projectMode==="cloud"){const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!key)return;const supabase=createBrowserClient(url,key);const {data:{user}}=await supabase.auth.getUser();if(!user){notify("请先登录后删除项目");return;}const {error}=await supabase.from("projects").delete().eq("id",id).eq("owner_id",user.id);if(error){notify("删除失败："+error.message);return;}}setProjectItems(prev=>prev.filter(p=>p.id!==id));notify(projectMode==="cloud"?"项目已删除":"演示项目已从当前页面移除");};
 const signOut=async()=>{const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const key=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(url&&key){const supabase=createBrowserClient(url,key);await supabase.auth.signOut();}window.location.href="/login";};
 const filteredResources=useMemo(()=>resources.filter(r=>(r.title+r.tags.join("")).toLowerCase().includes(query.toLowerCase())),[query]);const filteredSavedResources=useMemo(()=>savedResources.filter(r=>(r.title+(r.tags??[]).join("")).toLowerCase().includes(query.toLowerCase())),[savedResources,query]);
 const title=section==="交集"?"人脉机会":section;
 return <div className="min-h-screen bg-white text-[#091335]">
  <header className="fixed inset-x-0 top-0 z-40 flex h-[45px] items-center border-b border-[#eeeaf3] bg-white/95 px-4 backdrop-blur">
   <button className="mr-8 flex w-7 items-center justify-center text-[#282332]" onClick={()=>setSection("交集")} aria-label="首页"><Layers size={19}/></button>
   <div className="hidden max-w-[430px] flex-1 items-center gap-3 text-xs text-slate-400 md:flex"><Search size={14}/><input className="w-full bg-transparent outline-none placeholder:text-slate-400" placeholder="你想找的内容都在这里" value={query} onChange={e=>setQuery(e.target.value)}/></div>
   <div className="ml-auto flex items-center gap-3 text-slate-500"><button className="rounded-full bg-[#f7f3fc] p-1.5" onClick={()=>notify("主题设置将在后续版本开放")}><Sun size={14}/></button><button onClick={()=>notify("暂时没有新通知")}><Bell size={16}/></button><button onClick={()=>notify("消息中心将在后续版本开放")} className="relative"><MessageCircle size={16}/><i className="absolute -right-0.5 -top-0.5 h-1.5 w-1.5 rounded-full bg-rose-400"/></button><div className="hidden text-right sm:block"><div className="text-xs font-medium text-slate-700">{accountEmail?accountEmail.split("@")[0]:"演示访客"}</div><div className="text-[9px] text-slate-400">{accountEmail||"演示数据 · 未连接账号"}</div></div><button onClick={signOut} title="退出登录" className="grid h-7 w-7 place-items-center rounded-full bg-gradient-to-br from-[#9C88EC] to-[#8454F5] text-[10px] text-white"><LogOut size={13}/></button></div>
  </header>
  <aside className={`fixed bottom-0 left-0 top-[45px] z-30 w-[46px] border-r border-[#eeeaf3] bg-white transition-transform ${mobileNav?"translate-x-0":"-translate-x-full"} md:translate-x-0`}>
   <nav className="flex flex-col items-center pt-2">{nav.map(({name,icon:Icon})=><button key={name} onClick={()=>{setSection(name);setMobileNav(false)}} className={`flex h-[44px] w-full flex-col items-center justify-center gap-0.5 text-[9px] transition ${section===name?"bg-[#f5efff] text-[#8454F5]":"text-[#6e647b] hover:bg-[#faf8fd]"}`}><Icon size={16} strokeWidth={1.7}/>{name}</button>)}</nav>
   <div className="absolute bottom-4 flex w-full flex-col items-center gap-4 text-slate-400"><Bell size={15}/><div className="grid h-6 w-6 place-items-center rounded-full bg-[#f0edf3]"><UserRound size={13}/></div></div>
  </aside>
  <main className="min-h-screen pt-[45px] md:pl-[46px]">
   <div className="flex items-center justify-between px-4 pb-2 pt-3 md:hidden"><button onClick={()=>setMobileNav(!mobileNav)}><Menu size={20}/></button><span className="text-sm font-medium">{section}</span><span className="w-5"/></div>
   <div className="mx-auto max-w-[1600px] p-4 md:p-[22px]">
    {section==="交集"&&<div className="grid grid-cols-1 gap-4 xl:grid-cols-[minmax(0,1.75fr)_minmax(230px,.72fr)]">
     <div className="space-y-3"><section className="panel p-3"><div className="mb-3 flex items-center justify-between"><span className="text-sm font-semibold">人脉机会</span><span className="rounded bg-amber-50 px-2 py-1 text-[10px] text-amber-700">界面示例 · 暂无真实机会数据</span></div><div className="mb-2 flex gap-4 border-b pb-2 text-xs text-slate-500"><span className="border-b-2 border-[#8454F5] pb-2 text-[#8454F5]">人脉关系</span><span>项目机会</span><span>工作机会</span></div><div className="table-row grid-cols-[1fr_1.5fr_1.5fr_.7fr_.5fr] bg-[#faf9fb] px-2 font-medium text-slate-600"><span>人才需求</span><span>需求内容</span><span>项目名称</span><span>项目组长</span><span>操作</span></div>{["UX设计师","UXUI设计师","UI设计师","UXUI设计师"].map((v,i)=><div key={i} className="table-row grid-cols-[1fr_1.5fr_1.5fr_.7fr_.5fr] px-2"><span>{v}</span><span className="flex flex-wrap gap-1"><Tag>会使用Figma</Tag><Tag>用户研究</Tag><Tag>手绘</Tag></span><span className="truncate">{["残疾人专用手机APP设计","适老化小区改造服务设计"][i%2]}</span><span className="text-slate-500">👩🏻 王楠</span><button className="text-[#8454F5]" onClick={()=>notify("私信功能尚未接入，当前展示的是界面示例")}>了解</button></div>)}</section>
     <section className="panel p-3"><div className="mb-3 flex items-center justify-between"><div><span className="text-sm font-semibold">社区动态</span><p className="mt-1 text-[10px] text-amber-700">以下为展示用示例内容，不代表真实用户发布或互动数据</p></div><button className="text-xs text-[#8454F5]" onClick={()=>setShowNew(true)}>新建内容</button></div><div className="mb-3 flex gap-4 text-xs"><span className="text-[#8454F5]">关注</span><span className="text-slate-400">推荐</span><span className="text-slate-400">设计资讯</span></div>{posts.map((p,i)=><article key={p.title} className="flex gap-4 border-b border-[#f0edf3] py-3 last:border-0"><div className="min-w-0 flex-1"><div className="mb-2 flex items-center gap-2 text-[10px] text-slate-400"><span className="grid h-5 w-5 place-items-center rounded-full bg-gradient-to-br from-sky-300 to-indigo-700 text-white">示</span>示例作者 · 社区内容预览</div><h3 className="mb-1 text-[13px] font-medium text-slate-800">{p.title}</h3><p className="line-clamp-2 text-xs leading-5 text-slate-400">{p.desc}</p><div className="mt-3 flex gap-2 text-[10px] text-slate-400"><span className="rounded bg-[#F3F1FD] px-2 py-1">互动功能预览</span><span className="rounded bg-[#F3F1FD] px-2 py-1">文章详情待接入</span></div></div><div className="hidden h-[92px] w-[145px] shrink-0 rounded-sm md:block" style={{background:p.cover}}/></article>)}</section></div>
     <aside className="space-y-4"><section className="panel p-4"><div className="flex items-center gap-3"><div className="grid h-12 w-12 place-items-center rounded-full bg-gradient-to-br from-sky-200 via-slate-500 to-slate-950 text-white">示</div><div><div className="font-medium">教师主页预览</div><div className="mt-1 text-xs text-slate-400">用户研究 · 示例名片</div></div></div><div className="mt-5 grid grid-cols-3 gap-2 text-center"><div className="rounded bg-[#FAF9FC] px-2 py-3"><div className="text-[10px] text-slate-400">关注关系</div><b className="text-xs font-medium">功能预览</b></div><div className="rounded bg-[#FAF9FC] px-2 py-3"><div className="text-[10px] text-slate-400">社群互动</div><b className="text-xs font-medium">开发中</b></div><div className="rounded bg-[#FAF9FC] px-2 py-3"><div className="text-[10px] text-slate-400">内容发布</div><b className="text-xs font-medium">待接入</b></div></div></section><section className="flex min-h-[300px] items-center justify-center overflow-hidden rounded-md bg-gradient-to-b from-[#faf6ff] to-white"><div className="text-center"><div className="text-8xl">🌸</div><div className="mt-2 text-6xl">👧🏻</div><div className="mt-2 text-3xl">☁️</div><p className="mt-3 text-xs text-slate-400">让设计成长被看见</p></div></section></aside>
    </div>}
    {section==="就业趋向"&&<CareerPlanner notify={notify}/>}
    {section==="项目管理"&&<div className="space-y-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><h1 className="text-sm font-semibold">项目管理</h1><p className="mt-1 text-xs text-slate-400">统一管理设计实践，持续记录项目进展</p></div><div className="flex items-center gap-2"><span className={`rounded px-2.5 py-1.5 text-[10px] ${projectMode==="cloud"?"bg-emerald-50 text-emerald-700":"bg-amber-50 text-amber-700"}`}>{projectMode==="cloud"?"云端数据 · 已连接":"演示模式 · 本地临时数据"}</span><button onClick={()=>openProjectModal()} className="rounded bg-[#8454F5] px-3 py-2 text-xs text-white">＋ 新建项目</button></div></div><div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><Metric icon={FolderKanban} label="全部项目" value={String(projectItems.length)} tone="bg-violet-50 text-violet-500"/><Metric icon={Clock3} label="进行中项目" value={String(projectItems.filter(p=>p.status==="active").length)} tone="bg-emerald-50 text-emerald-500"/><Metric icon={CheckCircle2} label="已完成项目" value={String(projectItems.filter(p=>p.status==="completed").length)} tone="bg-amber-50 text-amber-500"/><Metric icon={Circle} label="待启动 / 已取消" value={String(projectItems.filter(p=>p.status==="planning"||p.status==="cancelled").length)} tone="bg-slate-100 text-slate-400"/></div><div className="grid gap-4 xl:grid-cols-[minmax(0,1.7fr)_280px]"><section className="panel min-w-0 p-3"><div className="mb-3 flex items-center justify-between"><b className="text-sm">项目信息</b><span className="text-[10px] text-slate-400">{projectLoading?"正在同步…":projectItems.length+" 个项目"}</span></div><div className="mb-3 rounded bg-[#faf9fb] p-3 text-xs leading-5 text-slate-500">{projectMode==="cloud"?"项目数据按当前登录账号隔离保存，访问权限由数据库 RLS 策略控制。":"当前为示例项目。新建、编辑和删除仅影响本次页面状态；登录并配置 Supabase 后可启用云端保存。"}</div>{projectItems.length===0?<div className="rounded bg-[#FAF9FC] py-14 text-center"><FolderKanban className="mx-auto text-[#9C88EC]" size={28}/><p className="mt-3 text-sm text-slate-500">还没有项目</p><button onClick={()=>openProjectModal()} className="mt-4 rounded bg-[#8454F5] px-4 py-2 text-xs text-white">创建项目</button></div>:<div className="overflow-x-auto"><div className="min-w-[720px]"><div className="table-row grid-cols-[1.5fr_.7fr_.7fr_1fr_.8fr] bg-[#faf9fb] px-2 font-medium text-slate-500"><span>项目名称</span><span>项目状态</span><span>项目类型</span><span>项目时间</span><span>操作</span></div>{projectItems.map(p=><div key={p.id} className="table-row grid-cols-[1.5fr_.7fr_.7fr_1fr_.8fr] px-2"><div className="min-w-0"><div className="truncate text-xs font-medium">{p.title}</div><div className="mt-1 truncate text-[10px] text-slate-400">{p.description||"暂无项目描述"}</div></div><Status value={projectStatusLabel[p.status]}/><span className="text-[10px] text-slate-500">{p.category}</span><span className="text-[10px] text-slate-500">{p.start_date||"未设置"} — {p.end_date||"未设置"}</span><div className="flex items-center gap-2 text-[11px]"><button className="text-[#8454F5]" onClick={()=>openProjectModal(p)}>编辑</button><button className="text-slate-400 hover:text-rose-500" onClick={()=>deleteProject(p.id)}>删除</button></div></div>)}</div></div>}</section><aside className="panel p-4"><b className="text-sm">项目概览</b><p className="mt-1 text-[10px] text-slate-400">当前项目状态分布</p><div className="my-5 space-y-4">{(["active","planning","completed","cancelled"] as ProjectRecord["status"][]).map(status=>{const count=projectItems.filter(p=>p.status===status).length;const percent=projectItems.length?count/projectItems.length*100:0;return <div key={status}><div className="mb-1.5 flex justify-between text-xs"><span className="text-slate-500">{projectStatusLabel[status]}</span><b className="text-slate-700">{count}</b></div><div className="h-1.5 overflow-hidden rounded-full bg-[#f0edf5]"><div className="h-full rounded-full bg-[#9C88EC]" style={{width:percent+"%"}}/></div></div>})}</div><div className="rounded bg-[#F7F3FF] p-3"><div className="text-xs font-medium text-[#8454F5]">项目管理提示</div><p className="mt-1 text-[10px] leading-5 text-slate-500">补充项目时间并定期更新状态，便于复盘阶段成果。</p></div></aside></div></div>}
    {section==="知识图谱"&&<KnowledgeHub notify={notify}/>}
    {section==="资源库"&&<div className="space-y-5"><section className="panel p-4"><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><div><b className="text-sm">学习记录</b><p className="mt-1 text-[10px] text-slate-400">记录每天的学习主题与投入时间，持续追踪成长</p></div><Tag>{resourceLoading?"同步中":resourceMode==="cloud"?"云端同步":"本地演示"}</Tag></div><div className="grid gap-2 md:grid-cols-[1.4fr_.8fr_.6fr]"><input value={studyForm.title} onChange={e=>setStudyForm(p=>({...p,title:e.target.value}))} placeholder="今天学习了什么？" className="rounded border px-3 py-2 text-xs outline-none focus:border-[#8454F5]"/><select value={studyForm.record_type} onChange={e=>setStudyForm(p=>({...p,record_type:e.target.value}))} className="rounded border bg-white px-3 py-2 text-xs"><option>课程学习</option><option>项目实践</option><option>阅读研究</option><option>技能练习</option><option>作品复盘</option></select><input type="number" min="1" max="1440" value={studyForm.minutes} onChange={e=>setStudyForm(p=>({...p,minutes:e.target.value}))} className="rounded border px-3 py-2 text-xs" aria-label="学习分钟数"/></div><input value={studyForm.note} onChange={e=>setStudyForm(p=>({...p,note:e.target.value}))} placeholder="学习备注（选填）" className="mt-2 w-full rounded border px-3 py-2 text-xs outline-none focus:border-[#8454F5]"/><div className="mt-3 flex items-center justify-between"><span className="text-[10px] text-slate-400">累计记录 {studyRecords.reduce((sum,r)=>sum+(Number(r.minutes)||0),0)} 分钟（最近 20 条）</span><button disabled={studySaving} onClick={saveStudyRecord} className="rounded bg-[#8454F5] px-4 py-2 text-xs text-white disabled:opacity-50">{studySaving?"保存中…":"记录本次学习"}</button></div>{studyRecords.length>0&&<div className="mt-4 divide-y border-t">{studyRecords.slice(0,5).map(r=><div key={r.id} className="flex items-center justify-between gap-3 py-2.5"><div className="min-w-0"><div className="truncate text-xs font-medium">{r.title}</div><div className="mt-1 text-[10px] text-slate-400">{r.record_type} · {new Date(r.created_at).toLocaleDateString("zh-CN")}</div></div><b className="shrink-0 text-xs text-[#8454F5]">{r.minutes} 分钟</b></div>)}</div>}</section><section><div className="mb-3 flex items-center justify-between"><b className="text-sm">推荐学习资源</b><span className="text-[10px] text-slate-400">收藏后加入个人资源库</span></div><div className="mb-3 flex items-center gap-2 rounded border px-3 py-2 md:max-w-xs"><Search size={14} className="text-slate-400"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索推荐资源" className="w-full text-xs outline-none"/></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{filteredResources.map(r=>{const saved=savedResources.some(x=>x.title===r.title);return <article key={r.title} className="overflow-hidden rounded border hover:shadow-soft"><div className="flex h-36 flex-col justify-between p-4 text-white" style={{background:r.color}}><BookOpen size={22}/><div className="text-sm font-medium">{r.title}</div></div><div className="flex items-center justify-between p-3"><Tag>{r.type}</Tag><button disabled={resourceSaving||saved} onClick={()=>saveResource(r)} className="flex items-center gap-1 text-[10px] text-[#8454F5] disabled:text-slate-400"><Bookmark size={13} fill={saved?"currentColor":"none"}/>{saved?"已收藏":"收藏资源"}</button></div></article>})}</div></section><section><div className="mb-3 flex items-center justify-between"><b className="text-sm">我的资源库</b><span className="text-[10px] text-slate-400">{filteredSavedResources.length} 项 · {resourceMode==="cloud"?"云端":"本地"}</span></div>{filteredSavedResources.length===0?<div className="rounded border border-dashed py-8 text-center text-xs text-slate-400">还没有收藏资源，先从上方推荐中收藏一项吧</div>:<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{filteredSavedResources.map(r=><article key={r.id} className="panel p-3"><div className="flex items-start justify-between gap-2"><div className="min-w-0"><b className="text-xs">{r.title}</b><div className="mt-2 flex flex-wrap gap-1">{(r.tags??[]).map((tag:string)=><Tag key={tag}>{tag}</Tag>)}</div></div><button onClick={()=>removeResource(r.id)} aria-label={"移除"+r.title} className="text-xs text-slate-400 hover:text-rose-500">移除</button></div><div className="mt-3 text-[10px] text-slate-400">{r.resource_type} · 收藏于 {new Date(r.created_at).toLocaleDateString("zh-CN")}</div></article>)}</div>}</section></div>}
    {section==="展示展厅"&&<div className="space-y-4"><div className="rounded-sm bg-gradient-to-r from-[#1a2364] via-[#6338a4] to-[#e28b9c] px-8 py-9 text-white"><div className="text-[10px] tracking-[.55em] opacity-80">DESIGN · PORTFOLIO · COMMUNITY</div><div className="mt-3 text-3xl font-light tracking-[.2em]">设计的无限可能</div><p className="mt-2 text-xs text-white/70">发现灵感，分享作品，让每一次创作都被看见。</p></div><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2 rounded-full border px-4 py-2 text-xs text-slate-400"><Search size={14}/><input placeholder="搜索项目中的创意世界" className="w-48 outline-none"/></div><div className="flex gap-3 text-xs text-slate-500"><button className="text-[#8454F5]">项目</button><button>图像</button><button>人物</button><button>资产</button><button>主题</button></div></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{["交互体验探索","植物与情绪视觉研究","品牌包装设计","移动端产品体验","城市公共艺术","字体与版式实验","数字产品概念","服务设计研究"].map((s,i)=><button key={s} onClick={()=>notify("打开作品详情："+s)} className="overflow-hidden rounded border text-left hover:shadow-soft"><div className={`flex h-44 items-center justify-center text-5xl text-white ${["bg-gradient-to-br from-indigo-500 to-sky-300","bg-gradient-to-br from-blue-200 to-emerald-500","bg-gradient-to-br from-slate-200 to-emerald-700","bg-gradient-to-br from-slate-800 to-black","bg-gradient-to-br from-orange-300 to-rose-500","bg-gradient-to-br from-fuchsia-400 to-violet-700","bg-gradient-to-br from-slate-300 to-blue-600","bg-gradient-to-br from-amber-200 to-red-500"][i]}`}>{["✳","❀","▤","▣","◉","Aa","◇","✦"][i]}</div><div className="p-3"><div className="text-xs font-medium">{s}</div><div className="mt-2 flex justify-between text-[10px] text-slate-400"><span>设计学习者</span><span><Heart size={11} className="mr-1 inline"/>40　< Eye size={11} className="mr-1 inline"/> 4w</span></div></div></button>)}</div></div>}
    {section==="我的主页"&&<div className="space-y-0"><div className="h-[120px] rounded-t bg-gradient-to-r from-[#102e68] via-[#1262a7] to-[#193a76]"/><div className="grid gap-5 px-2 md:grid-cols-[210px_1fr]"><section className="-mt-16 h-fit rounded border bg-white p-4 text-center shadow-soft"><div className="mx-auto grid h-20 w-20 place-items-center rounded-full bg-gradient-to-br from-violet-300 via-[#8454F5] to-indigo-700 text-3xl text-white">{profile.display_name.slice(0,1)||"学"}</div><h2 className="mt-2 font-medium">{profile.display_name}</h2><p className="mt-1 text-xs text-slate-400">{profile.career_goal||"正在探索职业方向"}</p><p className="mt-1 break-all text-[10px] text-slate-400">{accountEmail||"演示账号"}</p><p className="mt-3 text-xs text-slate-500"><MapPin size={12} className="mr-1 inline"/>{profile.school||"尚未填写学校"}</p><div className="mt-5 space-y-2 text-xs text-slate-500"><div className="flex justify-between"><span>专业</span><span>{profile.major||"未填写"}</span></div><div className="flex justify-between"><span>年级</span><span>{profile.grade||"未填写"}</span></div></div><button onClick={()=>{setProfileDraft(profile);setProfileEditing(true);}} className="mt-5 w-full rounded border border-[#8454F5] px-3 py-2 text-xs text-[#8454F5]">编辑个人资料</button></section><section className="pt-3"><div className="mb-4 flex gap-5 border-b text-xs">{["作品","交集","设计竞争力"].map(t=><button key={t} onClick={()=>setProfileTab(t)} className={`border-b-2 px-1 pb-3 ${profileTab===t?"border-[#8454F5] text-[#8454F5]":"border-transparent text-slate-500"}`}>{t}</button>)}</div>{profileTab==="作品"?<div className="space-y-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="text-sm font-medium">我的作品集</div><p className="mt-1 text-xs text-slate-400">{portfolioMode==="cloud"?"作品与图片已连接当前账号，可跨设备访问":"演示模式 · 未连接 Supabase 时仅保存在当前页面"}</p></div><button onClick={()=>openPortfolioModal()} className="flex items-center gap-1.5 rounded bg-[#8454F5] px-3 py-2 text-xs text-white"><Plus size={14}/>添加作品</button></div>{portfolioLoading?<div className="rounded border p-8 text-center text-xs text-slate-400">正在加载作品…</div>:portfolioItems.length===0?<div className="rounded border border-dashed p-10 text-center"><div className="text-sm font-medium">还没有作品</div><p className="mt-2 text-xs text-slate-400">上传你的第一个项目封面，逐步建立个人作品集。</p><button onClick={()=>openPortfolioModal()} className="mt-4 rounded border border-[#8454F5] px-4 py-2 text-xs text-[#8454F5]">创建第一件作品</button></div>:<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{portfolioItems.map(item=><article key={item.id} className="overflow-hidden rounded border bg-white"><div className="flex h-44 items-center justify-center overflow-hidden bg-gradient-to-br from-[#eee9ff] to-[#dbeafe]">{item.cover_url?<img src={item.cover_url} alt={item.title} className="h-full w-full object-cover"/>:<div className="text-4xl text-[#8454F5]">✳</div>}</div><div className="p-3"><div className="flex items-start justify-between gap-2"><b className="text-xs">{item.title}</b><div className="flex shrink-0 gap-2 text-[10px]"><button onClick={()=>openPortfolioModal(item)} className="text-[#8454F5]">编辑</button><button onClick={()=>deletePortfolio(item.id)} className="text-slate-400 hover:text-rose-500">删除</button></div></div>{item.description&&<p className="mt-2 line-clamp-2 text-[11px] leading-5 text-slate-500">{item.description}</p>}{(item.tags??[]).length>0&&<div className="mt-2 flex flex-wrap gap-1">{item.tags.map((tag:string)=><Tag key={tag}>{tag}</Tag>)}</div>}<div className="mt-3 text-[10px] text-slate-400">{item.created_at?new Date(item.created_at).toLocaleDateString("zh-CN"):"刚刚"}</div></div></article>)}</div>}</div>:profileTab==="交集"?<div className="rounded border border-dashed p-10 text-center text-xs text-slate-400">暂时还没有动态内容</div>:<div className="grid gap-4 lg:grid-cols-2"><div className="panel p-4"><div className="flex items-center justify-between"><b className="text-sm">能力维度</b><span className="text-[10px] text-slate-400">来自知识图谱能力自评</span></div>{assessmentLoading?<div className="grid h-64 place-items-center text-xs text-slate-400">正在加载评估数据…</div>:profileRadar.length>=3?<div className="mt-2 h-64"><ResponsiveContainer width="100%" height="100%"><RadarChart data={profileRadar}><PolarGrid stroke="#eee8f5"/><PolarAngleAxis dataKey="subject" tick={{fontSize:11,fill:"#898292"}}/><Radar dataKey="A" stroke="#8454F5" fill="#8454F5" fillOpacity={.18}/><Tooltip/></RadarChart></ResponsiveContainer></div>:<div className="grid h-64 place-items-center rounded border border-dashed text-center"><div><p className="text-sm text-slate-500">还没有足够的能力评估数据</p><p className="mt-2 text-xs text-slate-400">完成知识图谱中的至少 3 项能力自评后，这里会生成你的能力画像。</p></div></div>}</div><div className="panel p-4"><div className="flex items-center justify-between"><b className="text-sm">成长趋势</b><span className="text-[10px] text-slate-400">按月累计学习时长</span></div>{profileGrowth.length>0?<div className="mt-2 h-64"><ResponsiveContainer width="100%" height="100%"><AreaChart data={profileGrowth}><CartesianGrid strokeDasharray="3 3" stroke="#eeeaf2"/><XAxis dataKey="month" tick={{fontSize:11}}/><YAxis hide/><Tooltip formatter={(value)=>[`${value} 分钟`,"学习时长"]}/><Area dataKey="value" name="学习时长" stroke="#8454F5" fill="#eadbff"/></AreaChart></ResponsiveContainer></div>:<div className="grid h-64 place-items-center rounded border border-dashed text-center"><div><p className="text-sm text-slate-500">还没有学习记录</p><p className="mt-2 text-xs text-slate-400">在资源库记录学习主题和时长后，这里会展示你的成长趋势。</p></div></div>}</div></div>}</section></div></div>}

    {!nav.some(n=>n.name===section)&&null}
   </div>
  </main>
  {projectModal&&<div className="fixed inset-0 z-[55] flex items-center justify-center bg-black/25 p-4" onClick={()=>setProjectModal(false)}><div className="w-full max-w-lg rounded-lg bg-white p-5 shadow-xl" onClick={e=>e.stopPropagation()}><div className="mb-4 flex items-center justify-between"><b className="text-sm">{editingProject?"编辑项目":"新建项目"}</b><button onClick={()=>setProjectModal(false)}><X size={17}/></button></div><div className="space-y-3"><div><label className="mb-1.5 block text-xs text-slate-500">项目名称 *</label><input value={projectForm.title} onChange={e=>setProjectForm(p=>({...p,title:e.target.value}))} maxLength={100} className="w-full rounded border border-[#eeeaf4] px-3 py-2 text-sm outline-none focus:border-[#8454F5]" placeholder="输入项目名称"/></div><div><label className="mb-1.5 block text-xs text-slate-500">项目描述</label><textarea value={projectForm.description} onChange={e=>setProjectForm(p=>({...p,description:e.target.value}))} maxLength={1000} className="h-20 w-full resize-none rounded border border-[#eeeaf4] px-3 py-2 text-sm outline-none focus:border-[#8454F5]" placeholder="描述项目目标与设计内容"/></div><div className="grid gap-3 sm:grid-cols-2"><div><label className="mb-1.5 block text-xs text-slate-500">项目类型</label><select value={projectForm.category} onChange={e=>setProjectForm(p=>({...p,category:e.target.value}))} className="w-full rounded border border-[#eeeaf4] bg-white px-3 py-2 text-sm">{["交互设计","产品设计","服务设计","视觉设计","用户研究","其他"].map(v=><option key={v}>{v}</option>)}</select></div><div><label className="mb-1.5 block text-xs text-slate-500">项目状态</label><select value={projectForm.status} onChange={e=>setProjectForm(p=>({...p,status:e.target.value as ProjectRecord["status"]}))} className="w-full rounded border border-[#eeeaf4] bg-white px-3 py-2 text-sm">{(["planning","active","completed","cancelled"] as ProjectRecord["status"][]).map(v=><option key={v} value={v}>{projectStatusLabel[v]}</option>)}</select></div></div><div className="grid gap-3 sm:grid-cols-2"><div><label className="mb-1.5 block text-xs text-slate-500">开始日期</label><input type="date" value={projectForm.start_date} onChange={e=>setProjectForm(p=>({...p,start_date:e.target.value}))} className="w-full rounded border border-[#eeeaf4] px-3 py-2 text-sm"/></div><div><label className="mb-1.5 block text-xs text-slate-500">结束日期</label><input type="date" min={projectForm.start_date||undefined} value={projectForm.end_date} onChange={e=>setProjectForm(p=>({...p,end_date:e.target.value}))} className="w-full rounded border border-[#eeeaf4] px-3 py-2 text-sm"/></div></div></div><div className="mt-5 flex justify-end gap-2"><button onClick={()=>setProjectModal(false)} className="rounded border border-[#eeeaf4] px-4 py-2 text-xs">取消</button><button disabled={projectSaving} onClick={saveProject} className="rounded bg-[#8454F5] px-4 py-2 text-xs text-white disabled:opacity-60">{projectSaving?"保存中…":"保存项目"}</button></div></div></div>}
  {portfolioModal&&<div className="fixed inset-0 z-[57] flex items-center justify-center bg-black/25 p-4" onClick={()=>setPortfolioModal(false)}><div className="w-full max-w-lg rounded-lg bg-white p-5 shadow-xl" onClick={e=>e.stopPropagation()}><div className="mb-4 flex items-center justify-between"><b className="text-sm">{editingPortfolio?"编辑作品":"添加作品"}</b><button onClick={()=>setPortfolioModal(false)}><X size={17}/></button></div><div className="space-y-3"><label className="block text-xs text-slate-500">作品名称 *<input value={portfolioForm.title} onChange={e=>setPortfolioForm(v=>({...v,title:e.target.value}))} maxLength={100} className="mt-1 w-full rounded border px-3 py-2 text-sm outline-none focus:border-[#8454F5]" placeholder="例如：智能陪伴机器人交互设计"/></label><label className="block text-xs text-slate-500">作品简介<textarea value={portfolioForm.description} onChange={e=>setPortfolioForm(v=>({...v,description:e.target.value}))} maxLength={1000} rows={3} className="mt-1 w-full rounded border px-3 py-2 text-sm outline-none focus:border-[#8454F5]" placeholder="介绍项目背景、设计目标与成果"/></label><label className="block text-xs text-slate-500">作品标签<input value={portfolioForm.tags} onChange={e=>setPortfolioForm(v=>({...v,tags:e.target.value}))} className="mt-1 w-full rounded border px-3 py-2 text-sm outline-none focus:border-[#8454F5]" placeholder="交互设计，AI产品，用户研究"/></label><label className="block text-xs text-slate-500">封面图片（JPG / PNG / WebP / GIF，最大 10MB）<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" onChange={e=>setPortfolioFile(e.target.files?.[0]??null)} className="mt-1 block w-full rounded border p-2 text-xs file:mr-3 file:rounded file:border-0 file:bg-[#F3F1FD] file:px-3 file:py-1.5 file:text-[#8454F5]"/>{portfolioFile&&<span className="mt-1 block text-[10px] text-slate-400">{portfolioFile.name}</span>}</label><p className="text-[10px] leading-5 text-slate-400">{portfolioMode==="cloud"?"图片将上传至当前账号的作品存储空间。":"当前为本地演示模式，图片不会上传到云端。"}</p></div><div className="mt-5 flex justify-end gap-2"><button onClick={()=>setPortfolioModal(false)} className="rounded border px-4 py-2 text-xs">取消</button><button disabled={portfolioSaving} onClick={savePortfolio} className="rounded bg-[#8454F5] px-4 py-2 text-xs text-white disabled:opacity-60">{portfolioSaving?"保存中…":"保存作品"}</button></div></div></div>}
  {profileEditing&&<div className="fixed inset-0 z-[58] flex items-center justify-center bg-black/25 p-4" onClick={()=>setProfileEditing(false)}><div className="w-full max-w-lg rounded-lg bg-white p-5 shadow-xl" onClick={e=>e.stopPropagation()}><div className="mb-4 flex items-center justify-between"><b className="text-sm">编辑个人资料</b><button onClick={()=>setProfileEditing(false)}><X size={17}/></button></div><div className="grid gap-3 sm:grid-cols-2">{([{key:"display_name",label:"昵称"},{key:"major",label:"专业"},{key:"school",label:"学校"},{key:"grade",label:"年级"},{key:"career_goal",label:"目标方向"}] as const).map(f=><label key={f.key} className="text-xs text-slate-500">{f.label}<input value={profileDraft[f.key]} onChange={e=>setProfileDraft(v=>({...v,[f.key]:e.target.value}))} maxLength={80} className="mt-1 w-full rounded border px-3 py-2 text-sm text-slate-800 outline-none focus:border-[#8454F5]"/></label>)}</div><label className="mt-3 block text-xs text-slate-500">个人简介<textarea value={profileDraft.bio} onChange={e=>setProfileDraft(v=>({...v,bio:e.target.value}))} maxLength={500} rows={3} className="mt-1 w-full rounded border px-3 py-2 text-sm text-slate-800 outline-none focus:border-[#8454F5]"/></label><div className="mt-5 flex justify-end gap-2"><button onClick={()=>setProfileEditing(false)} className="rounded border px-4 py-2 text-xs">取消</button><button disabled={profileSaving} onClick={saveProfile} className="rounded bg-[#8454F5] px-4 py-2 text-xs text-white disabled:opacity-50">{profileSaving?"保存中…":"保存资料"}</button></div></div></div>}
  {showNew&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-black/25 p-4" onClick={()=>setShowNew(false)}><div className="w-full max-w-md rounded-lg bg-white p-5 shadow-xl" onClick={e=>e.stopPropagation()}><div className="mb-4 flex items-center justify-between"><b className="text-sm">创建新内容</b><button onClick={()=>setShowNew(false)}><X size={17}/></button></div><label className="mb-2 block text-xs text-slate-500">名称</label><input id="new-item" placeholder="输入名称" className="w-full rounded border px-3 py-2 text-sm outline-none focus:border-[#8454F5]"/><label className="mb-2 mt-4 block text-xs text-slate-500">描述</label><textarea placeholder="补充说明（选填）" className="h-24 w-full resize-none rounded border px-3 py-2 text-sm outline-none focus:border-[#8454F5]"/><div className="mt-5 flex justify-end gap-2"><button className="rounded border px-4 py-2 text-xs" onClick={()=>setShowNew(false)}>取消</button><button className="rounded bg-[#8454F5] px-4 py-2 text-xs text-white" onClick={()=>notify("内容发布功能尚未接入，当前未创建或发布任何内容")}>创建</button></div></div></div>}
  {toast&&<div className="fixed bottom-6 left-1/2 z-[60] -translate-x-1/2 rounded-md bg-[#091335] px-4 py-2.5 text-xs text-white shadow-lg">{toast}</div>}
 </div>
}